t.script:
odoo.define('nthub_realestate.contract_approval_process', function (require) {
    'use strict';
    var publicWidget = require('web.public.widget');

    publicWidget.registry.ContractApproval = publicWidget.Widget.extend({
        selector: '#contract_page_container',
        events: {
            'click #confirm_signature_btn': '_onConfirmSignature',
            'click #clear_signature': '_onClearSignature',
        },

        start: function () {
            this._super.apply(this, arguments);
            this.signaturePad = null;
            this._initializeSummernote();
            this._initializeModalEvents();
        },

        _initializeSummernote: function() {
            this.$('.summernote-editor').summernote({ height: 150, toolbar: [['style', ['bold', 'italic', 'underline']],['para', ['ul', 'ol']]] });
        },

        _initializeModalEvents: function() {
            var self = this;
            var signatureModalEl = this.el.querySelector('#signatureModal');

            if (signatureModalEl) {
                signatureModalEl.addEventListener('shown.bs.modal', function() {
                    // Use a timeout to ensure the modal is fully rendered and sized
                    setTimeout(function() {
                        try {
                            // Check if the SignaturePad library is loaded
                            if (typeof SignaturePad === 'undefined') {
                                console.error('SignaturePad library not loaded.');
                                alert('Error: The signature library could not be loaded. Please check your connection and try again.');
                                return;
                            }

                            var canvas = self.el.querySelector('#signature_pad_container canvas');
                            if (!canvas) {
                                console.error('Canvas element for signature pad not found.');
                                return;
                            }

                            self.signaturePad = new SignaturePad(canvas, { backgroundColor: 'rgb(255, 255, 255)' });
                            self._resizeCanvas();

                            window.addEventListener('resize', self._resizeCanvas.bind(self));
                        } catch (e) {
                            console.error('Error initializing signature pad:', e);
                            alert('An unexpected error occurred while setting up the signature pad.');
                        }
                    }, 150); // Increased timeout slightly for more reliability
                });

                signatureModalEl.addEventListener('hidden.bs.modal', function() {
                     window.removeEventListener('resize', self._resizeCanvas.bind(self));
                });
            }
        },

        _resizeCanvas: function() {
            if (!this.signaturePad) return;
            var canvas = this.signaturePad.canvas;
            var ratio = Math.max(window.devicePixelRatio || 1, 1);
            canvas.width = canvas.offsetWidth * ratio;
            canvas.height = canvas.offsetHeight * ratio;
            canvas.getContext("2d").scale(ratio, ratio);
            this.signaturePad.clear();
        },

        _onClearSignature: function() {
            if (this.signaturePad) { this.signaturePad.clear(); }
        },

        _onConfirmSignature: function (ev) {
            var $btn = $(ev.currentTarget);
            if (!this.signaturePad || this.signaturePad.isEmpty()) {
                return alert("Please provide a signature first.");
            }
            $btn.attr('disabled', 'disabled').find('.spinner-border').removeClass('d-none');

            var articles = {};
            this.$('.summernote-editor').each(function() {
                articles[$(this).attr('name')] = $(this).summernote('code');
            });

            fetch(window.location.pathname, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': this.$('input[name="csrf_token"]').val() },
                body: JSON.stringify({ articles: articles, signature: this.signaturePad.toDataURL() })
            })
            .then(response => {
                if (!response.ok) { return response.json().then(err => { throw new Error(err.error || 'Server error'); }); }
                return response.json();
            })
            .then(data => {
                if (data.status === 'success') { window.location.reload(); } else { throw new Error(data.error); }
            })
            .catch(error => {
                alert("An error occurred: " + error.message);
                $btn.removeAttr('disabled').find('.spinner-border').addClass('d-none');
            });
        },
    });
});
